package com.example.campsitelottery

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Before
import org.junit.Test
import java.util.Date

/**
 * Documentation generated by Claude
 * Tests removing ratings: the totals math in [RatingPolicy] and the flow in [InMemoryRatingRepository].
 */
class RatingRemovalTest {

    private lateinit var repo: InMemoryRatingRepository

    @Before
    fun setUp() {
        repo = InMemoryRatingRepository(
            listOf(Campsite(campsiteId = "site1", ownerId = "owner")),
            raterNames = mapOf("guest1" to "Sam"),
        )
    }

    private fun rate(userId: String, stars: Int) =
        repo.submitRating("site1", userId, stars, onSuccess = {}, onFailure = { throw it })

    private fun remove(userId: String, campsiteId: String = "site1"): Exception? {
        var error: Exception? = null
        repo.removeRating(campsiteId, userId, onSuccess = {}, onFailure = { error = it })
        return error
    }

    private fun ratings(): List<CampsiteRating> {
        var result: List<CampsiteRating>? = null
        repo.getRatings("site1", onSuccess = { result = it }, onFailure = { throw it })
        return result!!
    }

    @Test
    fun removeTakesOneRatingOutOfTheTotals() {
        assertEquals(
            RatingPolicy.Totals(sum = 6, count = 2),
            RatingPolicy.remove(RatingPolicy.Totals(sum = 11, count = 3), removedStars = 5),
        )
    }

    @Test
    fun removingTheLastRatingResetsTheTotals() {
        assertEquals(RatingPolicy.Totals(), RatingPolicy.remove(RatingPolicy.Totals(sum = 4, count = 1), 4))
        assertEquals(RatingPolicy.Totals(), RatingPolicy.remove(RatingPolicy.Totals(), 4))
    }

    @Test
    fun removeNeverGoesBelowZero() {
        assertEquals(
            RatingPolicy.Totals(sum = 0, count = 1),
            RatingPolicy.remove(RatingPolicy.Totals(sum = 3, count = 2), removedStars = 5),
        )
    }

    @Test
    fun sortNewestFirstPutsUndatedLast() {
        val sorted = RatingPolicy.sortNewestFirst(
            listOf(
                CampsiteRating(userId = "none"),
                CampsiteRating(userId = "old", updatedAt = Date(1)),
                CampsiteRating(userId = "new", updatedAt = Date(2)),
            )
        )
        assertEquals(listOf("new", "old", "none"), sorted.map { it.userId })
    }

    @Test
    fun getRatingsListsEachRaterWithTheirName() {
        rate("guest1", 5)
        rate("guest2", 2)
        val byUser = ratings().associateBy { it.userId }
        assertEquals(5, byUser.getValue("guest1").stars)
        assertEquals("Sam", byUser.getValue("guest1").raterName)
        assertEquals("", byUser.getValue("guest2").raterName)
    }

    @Test
    fun removedRatingIsGoneAndAverageIsRecalculated() {
        rate("guest1", 1)
        rate("guest2", 5)
        assertNull(remove("guest1"))
        assertEquals(listOf("guest2"), ratings().map { it.userId })
        assertEquals(RatingPolicy.Totals(sum = 5, count = 1), repo.totalsFor("site1"))
    }

    @Test
    fun removedUserNoLongerHasARating() {
        rate("guest1", 3)
        remove("guest1")
        var mine: Int? = -1
        repo.getMyRating("site1", "guest1", onSuccess = { mine = it }, onFailure = { throw it })
        assertNull(mine)
    }

    @Test
    fun removingTwiceFails() {
        rate("guest1", 3)
        assertNull(remove("guest1"))
        assertNotNull(remove("guest1"))
        assertEquals(RatingPolicy.Totals(), repo.totalsFor("site1"))
    }

    @Test
    fun removingFromUnknownCampsiteFails() {
        assertNotNull(remove("guest1", campsiteId = "missing"))
    }

    @Test
    fun failuresAreReported() {
        rate("guest1", 3)
        repo.failWith = IllegalStateException("offline")
        assertEquals("offline", remove("guest1")?.message)
        repo.failWith = null
        assertTrue(ratings().isNotEmpty())
    }
}
